:root {
  /* Colors */
  --color-lapis-frame: #117bc8;
  --color-cloud-paper: #ffffff;
  --color-cloud-glass: #ffffffe5;
  --color-mist-band: #f2f6fc;
  --color-fog-track: #ebebeb;
  --color-ink: #000000;
  --color-graphite-text: #2b2b2b;
  --color-pewter-caption: #7d7d7d;
  --color-ash-caption: #a1a1a1;
  --color-pebble-bezel: #dadada;
  --color-frost-ring: #ffffff60;
  --color-frost-hairline: #ffffff15;
  --color-smoke-glass: #00000010;

  /* Typography — Font Families */
  --font-signifier: "Signifier", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-switzer: "Switzer", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.24;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.24;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.24;
  --tracking-body-sm: 0px;
  --text-body: 17px;
  --leading-body: 1.2;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.24;
  --tracking-body-lg: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.0;
  --tracking-subheading: 0px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.24;
  --tracking-heading-sm: 0px;
  --text-heading: 34px;
  --leading-heading: 1.02;
  --tracking-heading: 0px;
  --text-heading-lg: 45px;
  --leading-heading-lg: 1.02;
  --tracking-heading-lg: 0px;
  --text-display: 55px;
  --leading-display: 1.18;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-15: 15px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-23: 23px;
  --spacing-24: 24px;
  --spacing-38: 38px;
  --spacing-65: 65px;
  --spacing-108: 108px;

  /* Layout */
  --layout-max-width: 1440px;
  --layout-section-gap: 108px;
  --layout-card-padding: 15px;
  --layout-element-gap: 8px;
  --layout-nav-height: 124px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-md-2: 10px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 6px;
  --radius-inner-tiles: 8px;
  --radius-small-cards: 10px;
  --radius-cards: 12px;
  --radius-images: 16px;
  --radius-sections: 20px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 4px 10px 0px rgba(0, 0, 0, 0.07);
  --shadow-sm: 0px 5px 4px 0px rgba(0, 0, 0, 0.1);
  --shadow-md: 5px 8px 8px -2px rgba(0, 0, 0, 0.25), -4px -1px 8px -2px rgba(0, 0, 0, 0.2);
  --shadow-md-2: 5px 8px 8px 0px rgba(0, 0, 0, 0.25), -4px -6px 8px 0px rgba(0, 0, 0, 0.25);
  --shadow-lg: 0px 4px 3px -2px rgba(0, 0, 0, 0.2), 0px 3px 8px 1px rgba(0, 0, 0, 0.12), 0px 5px 5px 1px rgba(0, 0, 0, 0.14);

  /* Surfaces */
  --surface-lapis-frame: #117bc8;
  --surface-mist-band: #f2f6fc;
  --surface-cloud-paper: #ffffff;
  --surface-cloud-glass: #ffffffe5;
  --surface-smoke-glass: #00000010;
  --surface-glass-blur: 20px;
}

